def transform(grid):
    if not grid: 
        return grid
    R = len(grid)
    C = len(grid[0])
    if not C: 
        return [[0] * R for _ in range(R)]

    # Count frequencies to find background B
    counts = {}
    for r in range(R):
        for c in range(C):
            v = grid[r][c]
            counts[v] = counts.get(v, 0) + 1
    B = max(counts.keys(), key=lambda k: counts[k])

    # Identify separator value S (uniform row/col value != B)
    sep_candidates = set()
    for c in range(C):
        val = grid[0][c]
        if all(grid[r][c] == val for r in range(R)):
            sep_candidates.add(val)
    for r in range(R):
        val = grid[r][0]
        if all(grid[r][c] == val for c in range(C)):
            sep_candidates.add(val)

    S = None
    for val in sep_candidates:
        if val != B:
            S = val
            break
    if S is None:
        S = 0 # Fallback

    # Calculate shift
    shift = S + B

    # Identify separator lines
    sep_rows = []
    sep_cols = []
    for r in range(R):
        val = grid[r][0]
        if val == S and all(grid[r][c] == val for c in range(C)):
            sep_rows.append(r)
    for c in range(C):
        val = grid[0][c]
        if val == S and all(grid[r][c] == val for r in range(R)):
            sep_cols.append(c)

    # Define coordinate intervals
    row_intervals = []
    curr = 0
    for r in sep_rows:
        if r > curr:
            row_intervals.append((curr, r - 1))
        curr = r + 1
    if curr < R:
        row_intervals.append((curr, R - 1))

    col_intervals = []
    curr = 0
    for c in sep_cols:
        if c > curr:
            col_intervals.append((curr, c - 1))
        curr = c + 1
    if curr < C:
        col_intervals.append((curr, C - 1))

    # Initialize result
    res = [[0] * C for _ in range(R)]

    # Fill separators
    for r in sep_rows:
        for c in range(C):
            res[r][c] = S
    for c in sep_cols:
        for r in range(R):
            res[r][c] = S

    # Fill regions
    for r_inicio, r_fin in row_intervals:
        for c_inicio, c_fin in col_intervals:
            markers = set()
            for r in range(r_inicio, r_fin + 1):
                for c in range(c_inicio, c_fin + 1):
                    v = grid[r][c]
                    if v != B and v != S:
                        markers.add(v)

            if markers:
                marker = list(markers)[0]
                color = marker + shift
                for r in range(r_inicio, r_fin + 1):
                    for c in range(c_inicio, c_fin + 1):
                        res[r][c] = color
            else:
                color = shift
                for r in range(r_inicio, r_fin + 1):
                    for c in range(c_inicio, c_fin + 1):
                        res[r][c] = color

    return res
